-- VERIFICACION DE DATOS Y RESULTADOS DEL DASHBOARD
SELECT 'hotel' AS tabla, COUNT(*) AS registros FROM catalogo.hotel
UNION ALL SELECT 'tipo_habitacion', COUNT(*) FROM catalogo.tipo_habitacion
UNION ALL SELECT 'servicio', COUNT(*) FROM catalogo.servicio
UNION ALL SELECT 'empleado', COUNT(*) FROM operaciones.empleado
UNION ALL SELECT 'habitacion', COUNT(*) FROM catalogo.habitacion
UNION ALL SELECT 'huesped', COUNT(*) FROM operaciones.huesped
UNION ALL SELECT 'reservacion', COUNT(*) FROM operaciones.reservacion
UNION ALL SELECT 'estancia', COUNT(*) FROM operaciones.estancia
UNION ALL SELECT 'acompanante', COUNT(*) FROM operaciones.acompanante
UNION ALL SELECT 'consumo_servicio', COUNT(*) FROM operaciones.consumo_servicio
UNION ALL SELECT 'factura', COUNT(*) FROM finanzas.factura
UNION ALL SELECT 'detalle_factura', COUNT(*) FROM finanzas.detalle_factura;
GO
-- Si ya creaste las tres vistas, prueba sus resultados:
IF OBJECT_ID('operaciones.vw_tipos_habitacion_mas_reservados', 'V') IS NOT NULL EXEC('SELECT nombre_tipo, total_reservas, posicion FROM operaciones.vw_tipos_habitacion_mas_reservados ORDER BY posicion, nombre_tipo');
IF OBJECT_ID('operaciones.vw_reservas_por_canal_estado', 'V') IS NOT NULL EXEC('SELECT canal_reserva, pendientes, confirmadas, canceladas, posicion FROM operaciones.vw_reservas_por_canal_estado ORDER BY posicion');
IF OBJECT_ID('operaciones.vw_huespedes_por_nacionalidad', 'V') IS NOT NULL EXEC('SELECT nacionalidad, total_huespedes, posicion FROM operaciones.vw_huespedes_por_nacionalidad ORDER BY posicion, nacionalidad');
GO
